//! Spark's built-in function catalog, as executed Spark releases report it
//! (`vendored/spark-functions.tsv`, generated by
//! `tests/scripts/gen_function_registry.py`): every name, the first release
//! line that has it, whether Spark analyzes it as deterministic, its kind
//! and its arity.

use crate::signature::{Arity, FunctionKind, SparkProfile};

/// The vendored catalog.
const TSV: &str = include_str!("../../vendored/spark-functions.tsv");

/// One name of Spark's catalog.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SparkFunction {
    /// The name, as `SHOW FUNCTIONS` lists it.
    pub name: &'static str,
    /// Which registry lists it: `function`, `table_function` or `operator`.
    pub registry: &'static str,
    /// The oldest supported release line that has it.
    pub since: SparkProfile,
    /// `Expression.deterministic` of an analyzed call; `None` when no call
    /// analyzed (Spark rejected every probe).
    pub deterministic: Option<bool>,
    /// The kind of an analyzed call (`None` when unknown).
    pub kind: Option<FunctionKind>,
    /// The argument counts Spark's arity check accepts.
    pub arity: Arity,
}

/// One catalog row, or `None` for a malformed one (the tests check there
/// are none).
fn row(line: &'static str) -> Option<SparkFunction> {
    let mut cols = line.split('\t');
    let mut next = || cols.next();
    let (name, registry, since, det, kind, counts, expected) = (
        next()?,
        next()?,
        next()?,
        next()?,
        next()?,
        next()?,
        next()?,
    );
    let mut probed = [false; Arity::PROBED + 1];
    if counts.len() != probed.len() {
        return None;
    }
    for (slot, c) in probed.iter_mut().zip(counts.bytes()) {
        *slot = c == b'1';
    }
    Some(SparkFunction {
        name,
        registry,
        since: SparkProfile::from_line(since)?,
        deterministic: match det {
            "true" => Some(true),
            "false" => Some(false),
            _ => None,
        },
        kind: match kind {
            "scalar" => Some(FunctionKind::Scalar),
            "aggregate" => Some(FunctionKind::Aggregate),
            "window" => Some(FunctionKind::Window),
            "generator" => Some(FunctionKind::Generator),
            _ => None,
        },
        arity: Arity::new(probed, expected),
    })
}

/// The catalog's rows (comment lines skipped) and the number of malformed
/// rows.
pub(super) fn load() -> (Vec<SparkFunction>, usize) {
    let lines: Vec<&'static str> = TSV
        .lines()
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .collect();
    let rows: Vec<SparkFunction> = lines.iter().filter_map(|l| row(l)).collect();
    let malformed = lines.len().saturating_sub(rows.len());
    (rows, malformed)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_vendored_catalog_parses() {
        let (rows, malformed) = load();
        assert_eq!(malformed, 0);
        assert_eq!(rows.len(), 574);
        let upper = rows.iter().find(|r| r.name == "upper").unwrap();
        assert_eq!(upper.since, SparkProfile::V3_5);
        assert_eq!(upper.deterministic, Some(true));
        assert_eq!(upper.kind, Some(FunctionKind::Scalar));
        assert!(upper.arity.accepts(1) && !upper.arity.accepts(2));
        assert_eq!(upper.arity.expected(), "1");
        let rand = rows.iter().find(|r| r.name == "randstr").unwrap();
        assert_eq!(rand.since, SparkProfile::V4_0);
        assert_eq!(rand.deterministic, Some(false));
    }

    #[test]
    fn malformed_rows_are_rejected() {
        assert_eq!(row("a\tfunction\t4.2\ttrue\tscalar\t0100000"), None);
        assert_eq!(row("a\tfunction\t3.4\ttrue\tscalar\t0100000\t1"), None);
        assert_eq!(row("a\tfunction\t4.2\ttrue\tscalar\t01\t1"), None);
        let r = row("a\tfunction\t4.2\tunknown\tunknown\t1111111\t").unwrap();
        assert_eq!((r.deterministic, r.kind), (None, None));
        assert!(r.arity.accepts(9));
        let w = row("w\tfunction\t4.2\tfalse\tgenerator\t0100000\t1").unwrap();
        assert_eq!(
            (w.deterministic, w.kind),
            (Some(false), Some(FunctionKind::Generator))
        );
    }
}
